import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for the command line entry point of {@link IndexImage}.
 */
class IndexImageMainTests {

    private static final int RED = 0xFFFF0000;
    private static final int GREEN = 0xFF00FF00;
    private static final int BLUE = 0xFF0000FF;
    private static final int YELLOW = 0xFFFFFF00;
    private static final int CYAN = 0xFF00FFFF;
    private static final int MAGENTA = 0xFFFF00FF;

    @TempDir
    Path tempDir;

    private PrintStream originalOut;
    private PrintStream originalErr;
    private SecurityManager originalSecurityManager;
    private ByteArrayOutputStream capturedOut;
    private ByteArrayOutputStream capturedErr;

    @BeforeEach
    void captureConsoleAndTrapExit() throws Exception {
        originalOut = System.out;
        originalErr = System.err;
        originalSecurityManager = System.getSecurityManager();

        capturedOut = new ByteArrayOutputStream();
        capturedErr = new ByteArrayOutputStream();
        System.setOut(new PrintStream(capturedOut, true, StandardCharsets.UTF_8.name()));
        System.setErr(new PrintStream(capturedErr, true, StandardCharsets.UTF_8.name()));
        System.setSecurityManager(new NoExitSecurityManager());
    }

    @AfterEach
    void restoreConsoleAndSecurityManager() {
        try {
            System.setSecurityManager(originalSecurityManager);
        }
        finally {
            System.setOut(originalOut);
            System.setErr(originalErr);
        }
    }

    @Test
    void noArgumentsPrintsUsageAndExitsWithFive() {
        RunResult result = runIndexImage();

        assertUsageExit(result);
        assertEquals("", result.stdout, "Usage should be written to stderr only");
    }

    @ParameterizedTest
    @ValueSource(strings = {"-h", "--help"})
    void helpOptionPrintsUsageAndExitsWithFive(String helpOption) {
        RunResult result = runIndexImage(helpOption);

        assertUsageExit(result);
    }

    @Test
    void unknownOptionIsReportedWithoutPreventingAValidConversion() throws IOException {
        Path input = writeColorfulPng("unknown-option-input.png");
        Path output = tempDir.resolve("unknown-option-output.png");

        RunResult result = runIndexImage("--definitely-not-an-option", input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        assertTrue(result.stderr.contains("Unknown option \"--definitely-not-an-option\""), result.stderr);
        assertIndexedOutput(output, 8, 4);
    }

    @Test
    void inputAndOutputArgumentsCreateAnIndexedPngUsingTheOutputExtension() throws IOException {
        Path input = writeColorfulPng("inferred-format-input.png");
        Path output = tempDir.resolve("inferred-format-output.png");

        RunResult result = runIndexImage(input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        assertTrue(Files.size(output) > 0, "The converted file should not be empty");
        assertIndexedOutput(output, 8, 4);
    }

    @Test
    void explicitOutputFormatOverridesTheOutputFileExtension() throws IOException {
        Path input = writeColorfulPng("explicit-format-input.png");
        Path output = tempDir.resolve("explicit-format-output.data");

        RunResult result = runIndexImage("--outputformat", "PNG", input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        assertTrue(Files.size(output) > 0, "The converted file should not be empty");

        byte[] bytes = Files.readAllBytes(output);
        assertTrue(bytes.length >= 8, "PNG output should have a signature");
        assertEquals((byte) 0x89, bytes[0]);
        assertEquals((byte) 'P', bytes[1]);
        assertEquals((byte) 'N', bytes[2]);
        assertEquals((byte) 'G', bytes[3]);
        assertIndexedOutput(output, 8, 4);
    }

    @Test
    void unsupportedOutputFormatIsReportedButDoesNotCauseANonZeroExit() throws IOException {
        Path input = writeColorfulPng("unsupported-format-input.png");
        Path output = tempDir.resolve("unsupported-format-output.png");

        RunResult result = runIndexImage("--outputformat", "not-a-real-format", input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        assertTrue(result.stderr.contains("No writer for format: \"not-a-real-format\"!"), result.stderr);
    }

    @Test
    void existingOutputIsNotOverwrittenUnlessRequested() throws IOException {
        Path input = writeColorfulPng("no-overwrite-input.png");
        Path output = tempDir.resolve("no-overwrite-output.png");
        byte[] sentinel = "existing content".getBytes(StandardCharsets.UTF_8);
        Files.write(output, sentinel);

        RunResult result = runIndexImage(input.toString(), output.toString());

        assertEquals(5, result.status, result.stderr);
        assertTrue(result.stderr.contains("The file \"" + output.toFile().getAbsolutePath() + "\" allready exists!"), result.stderr);
        assertArrayEquals(sentinel, Files.readAllBytes(output));
    }

    @ParameterizedTest
    @ValueSource(strings = {"-w", "--overwrite"})
    void overwriteOptionAllowsAnExistingOutputToBeReplaced(String overwriteOption) throws IOException {
        Path input = writeColorfulPng("overwrite-input.png");
        Path output = tempDir.resolve("overwrite-output.png");
        Files.write(output, "existing content".getBytes(StandardCharsets.UTF_8));

        RunResult result = runIndexImage(overwriteOption, input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        assertIndexedOutput(output, 8, 4);
    }

    @Test
    void missingInputFileIsReportedAndExitsWithFive() throws IOException {
        Path missingInput = tempDir.resolve("does-not-exist.png");
        Path output = tempDir.resolve("missing-input-output.png");

        RunResult result = runIndexImage(missingInput.toString(), output.toString());

        assertEquals(5, result.status, result.stderr);
        assertTrue(result.stderr.contains("File \"" + missingInput.toFile().getAbsolutePath() + "\" does not exist!"), result.stderr);
        assertFalse(Files.exists(output), "No output should be written for a missing input");
    }

    @Test
    void fileWithoutAnImageReaderIsReportedAndExitsWithFive() throws IOException {
        Path input = tempDir.resolve("not-an-image.png");
        Files.write(input, "this is not an image".getBytes(StandardCharsets.UTF_8));
        Path output = tempDir.resolve("unreadable-input-output.png");

        RunResult result = runIndexImage(input.toString(), output.toString());

        assertEquals(5, result.status, result.stderr);
        assertTrue(result.stderr.contains("No reader for image: \"" + input.toFile().getAbsolutePath() + "\"!"), result.stderr);
        assertFalse(Files.exists(output), "No output should be written for an unreadable input");
    }

    @Test
    void missingPaletteFileIsReportedAndExitsWithFive() throws IOException {
        Path input = writeColorfulPng("missing-palette-input.png");
        Path missingPalette = tempDir.resolve("missing-palette.png");
        Path output = tempDir.resolve("missing-palette-output.png");

        RunResult result = runIndexImage("--palette", missingPalette.toString(), input.toString(), output.toString());

        assertEquals(5, result.status, result.stderr);
        assertTrue(result.stderr.contains("does not exist!"), result.stderr);
        assertFalse(Files.exists(output), "No output should be written when the palette is missing");
    }

    @ParameterizedTest
    @ValueSource(strings = {"-p", "--palette"})
    void paletteOptionRestrictsOutputToColorsFromThePalette(String paletteOption) throws IOException {
        byte[] reds = {(byte) 0xFF, 0, 0, 0};
        byte[] greens = {0, (byte) 0xFF, 0, 0};
        byte[] blues = {0, 0, (byte) 0xFF, 0};
        IndexColorModel paletteModel = new IndexColorModel(8, 4, reds, greens, blues);
        BufferedImage palette = new BufferedImage(4, 1, BufferedImage.TYPE_BYTE_INDEXED, paletteModel);
        palette.setRGB(0, 0, RED);
        palette.setRGB(1, 0, GREEN);
        palette.setRGB(2, 0, BLUE);
        palette.setRGB(3, 0, 0xFF000000);
        Path paletteFile = writePng("palette.png", palette);

        Path input = writeColorfulPng("palette-input.png");
        Path output = tempDir.resolve("palette-output.png");

        RunResult result = runIndexImage(paletteOption, paletteFile.toString(), "--dither", "none",
                input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        BufferedImage outputImage = assertIndexedOutputImage(output, 8, 4);
        Set<Integer> allowed = new HashSet<>();
        allowed.add(RED & 0xFFFFFF);
        allowed.add(GREEN & 0xFFFFFF);
        allowed.add(BLUE & 0xFFFFFF);
        allowed.add(0x000000);

        Set<Integer> used = usedRgbColors(outputImage);
        assertFalse(used.isEmpty(), "Expected the output to contain at least one palette color");
        for (int rgb : used) {
            assertTrue(allowed.contains(rgb), "Unexpected palette color: #" + Integer.toHexString(rgb));
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {"-g", "--grayscale"})
    void grayscaleOptionProducesAGrayscalePalette(String grayscaleOption) throws IOException {
        Path input = writeColorfulPng("grayscale-input.png");
        Path output = tempDir.resolve("grayscale-output.png");

        RunResult result = runIndexImage(grayscaleOption, input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        IndexColorModel colorModel = assertIndexedOutput(output, 8, 4);
        assertTrue(colorModel.getMapSize() > 0, "Expected at least one grayscale color");

        for (int i = 0; i < colorModel.getMapSize(); i++) {
            assertEquals(colorModel.getRed(i), colorModel.getGreen(i), "Palette entry " + i + " should be gray");
            assertEquals(colorModel.getGreen(i), colorModel.getBlue(i), "Palette entry " + i + " should be gray");
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {"-m", "--monochrome"})
    void monochromeOptionProducesATwoColorPalette(String monochromeOption) throws IOException {
        Path input = writeColorfulPng("monochrome-input.png");
        Path output = tempDir.resolve("monochrome-output.png");

        RunResult result = runIndexImage(monochromeOption, input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        IndexColorModel colorModel = assertIndexedOutput(output, 8, 4);
        assertEquals(2, colorModel.getMapSize(), "Monochrome output should contain exactly two colors");

        for (int i = 0; i < colorModel.getMapSize(); i++) {
            assertEquals(colorModel.getRed(i), colorModel.getGreen(i), "Monochrome palette entry " + i + " should be gray");
            assertEquals(colorModel.getGreen(i), colorModel.getBlue(i), "Monochrome palette entry " + i + " should be gray");
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {"-c", "--colors"})
    void colorsOptionLimitsTheSizeOfTheOutputPalette(String colorsOption) throws IOException {
        Path input = writeColorfulPng("colors-input.png");
        Path output = tempDir.resolve("colors-output.png");

        RunResult result = runIndexImage(colorsOption, "4", input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        BufferedImage outputImage = assertIndexedOutputImage(output, 8, 4);
        Set<Integer> used = usedRgbColors(outputImage);
        assertTrue(used.size() > 0, "Expected at least one output color");
        assertTrue(used.size() <= 4, "Expected at most four output colors, but was " + used.size());
    }

    @Test
    void invalidColorsValuePrintsUsageAndExitsWithFive() throws IOException {
        Path input = writeColorfulPng("invalid-colors-input.png");
        Path output = tempDir.resolve("invalid-colors-output.png");

        RunResult result = runIndexImage("--colors", "not-a-number", input.toString(), output.toString());

        assertUsageExit(result);
        assertFalse(Files.exists(output), "No output should be written after invalid arguments");
    }

    @ParameterizedTest
    @ValueSource(strings = {"-b", "--bgcolor"})
    void backgroundOptionIsAppliedUnderTransparentPixels(String backgroundOption) throws IOException {
        BufferedImage transparentInput = new BufferedImage(8, 4, BufferedImage.TYPE_INT_ARGB);
        int[] opaqueColors = {GREEN, BLUE, YELLOW, CYAN, MAGENTA, 0xFFFFFFFF, 0xFF000000};
        for (int y = 0; y < transparentInput.getHeight(); y++) {
            for (int x = 0; x < transparentInput.getWidth(); x++) {
                int rgb = ((x + y) % 2 == 0) ? 0x00000000 : opaqueColors[(x + y) % opaqueColors.length];
                transparentInput.setRGB(x, y, rgb);
            }
        }
        Path input = writePng("background-input.png", transparentInput);
        Path output = tempDir.resolve("background-output.png");

        RunResult result = runIndexImage(backgroundOption, "#ff0000", "--dither", "none",
                input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        BufferedImage outputImage = assertIndexedOutputImage(output, 8, 4);
        assertEquals(0xFF0000, outputImage.getRGB(0, 0) & 0xFFFFFF,
                "A fully transparent source pixel should be composited over the requested background");
        assertTrue(usedRgbColors(outputImage).contains(0xFF0000), "Expected the background color in the output");
    }

    @Test
    void invalidBackgroundColorPrintsUsageAndExitsWithFive() throws IOException {
        Path input = writeColorfulPng("invalid-background-input.png");
        Path output = tempDir.resolve("invalid-background-output.png");

        RunResult result = runIndexImage("--bgcolor", "not-a-color", input.toString(), output.toString());

        assertUsageExit(result);
        assertFalse(Files.exists(output), "No output should be written after invalid arguments");
    }

    @Test
    void transparencyOptionProducesATransparentPaletteEntry() throws IOException {
        BufferedImage imageWithTransparency = new BufferedImage(4, 2, BufferedImage.TYPE_INT_ARGB);
        imageWithTransparency.setRGB(0, 0, 0x00FF0000);
        imageWithTransparency.setRGB(1, 0, RED);
        imageWithTransparency.setRGB(2, 0, GREEN);
        imageWithTransparency.setRGB(3, 0, BLUE);
        imageWithTransparency.setRGB(0, 1, YELLOW);
        imageWithTransparency.setRGB(1, 1, CYAN);
        imageWithTransparency.setRGB(2, 1, MAGENTA);
        imageWithTransparency.setRGB(3, 1, 0x00000000);
        Path input = writePng("transparency-input.png", imageWithTransparency);
        Path output = tempDir.resolve("transparency-output.png");

        RunResult result = runIndexImage("--transparency", "--colors", "8", input.toString(), output.toString());

        assertEquals(0, result.status, result.stderr);
        IndexColorModel colorModel = assertIndexedOutput(output, 4, 2);
        assertTrue(colorModel.hasAlpha(), "The output palette should contain alpha information");

        boolean foundFullyTransparentEntry = false;
        for (int i = 0; i < colorModel.getMapSize(); i++) {
            if (colorModel.getAlpha(i) == 0) {
                foundFullyTransparentEntry = true;
                break;
            }
        }
        assertTrue(foundFullyTransparentEntry, "Expected a fully transparent palette entry");
    }

    @ParameterizedTest
    @CsvSource({
            "default, high",
            "none, low",
            "diffusion, high",
            "diffusion_altscans, low"
    })
    void ditherAndQualityOptionsAreAccepted(String dither, String quality) throws IOException {
